// Ambil data dari kedua cabang (index 0 = Get Product API, index 1 = Generate Recipe - MiniMax)
const productItems = $items('Get Product API');
const recipeItem = $items('Generate Recipe - MiniMax')[0];

// Sesuaikan path ini dengan struktur response API produk kamu
// Asumsi: API mengembalikan array of {id, name, ...} langsung, atau di dalam field 'data'
let products = [];
const rawProduct = productItems[0].json;
if (Array.isArray(rawProduct)) {
  products = rawProduct;
} else if (Array.isArray(rawProduct.data)) {
  products = rawProduct.data;
} else if (Array.isArray(rawProduct.products)) {
  products = rawProduct.products;
}

const productNames = products.map(p => (p.name || p.nama || '').toString().toLowerCase().trim());

// Parse response Sumopod (format OpenAI-compatible: choices[0].message.content)
let recipeData;
try {
  const rawText = recipeItem.json.choices[0].message.content;
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  recipeData = JSON.parse(cleaned);
} catch (err) {
  throw new Error('Gagal parse response Sumopod MiniMax: ' + err.message);
}

const dish = recipeData.dish;
const ingredients = recipeData.ingredients || [];

const tersedia = [];
const tidakTersedia = [];

for (const ing of ingredients) {
  const ingLower = ing.toLowerCase().trim();
  const found = productNames.some(pn => pn.includes(ingLower) || ingLower.includes(pn));
  if (found) {
    tersedia.push(ing);
  } else {
    tidakTersedia.push(ing);
  }
}

return [{
  json: {
    dish: dish,
    total_bahan: ingredients.length,
    bahan_tersedia: tersedia,
    bahan_tidak_tersedia: tidakTersedia
  }
}];
